    if (descriptor.charAt(pos) == '(') { // method descriptor
        pos++; // skip '('
        while (descriptor.charAt(pos) != ')') {
            // consume array dimensions
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            char c = descriptor.charAt(pos);
            if (c == 'L') { // object type
                pos = descriptor.indexOf(';', pos) + 1;
            } else { // primitive type
                pos++;
            }
            // pop one from the output frame stack
            outputFrameStack.pop();
        }
        pos++; // skip ')'
    } else { // single type descriptor
        while (descriptor.charAt(pos) == '[') {
            pos++;
