    try {
        if (terminators == null) {
            return "";
        }
        StringBuilder token = new StringBuilder();
        int ch = peek();
        while (ch != -1) {
            char c = (char) ch;
            boolean isTerminator = false;
            for (char t : terminators) {
                if (c == t) {
                    isTerminator = true;
                    break;
