private void moveAllListNodes(DoublyLinkedList<E> list){
    // Guard against null or moving to same list
    if (list == null || list == this) {
        return;
    }
    // Traverse the source list. We grab the next node before
    // removing the current one to avoid losing the link.
    ListNodeImpl<E> node = list.getFirst(); // assume accessor
    while (node != null) {
        ListNodeImpl<E> next = node.getNext(); // assume accessor
        // Remove from source and add to this list
        list.removeListNode(node);
        this.addListNode(node);
        node = next;
    }
}

