private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set cannot be null");
    }
    // A graph with zero or one vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue; // skip self-comparison
            }
            // graph.containsEdge may throw if either vertex not in the graph; we catch and treat as false
            try {
                if (!graph.containsEdge(v1, v2)) {
                    return false;
                }
            } catch (Exception e) {
                return false;
            }
        }
    }
    return true;
}

