private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        // Read the first byte and determine the UTF-8 sequence length
        int b0 = bb.get() & 0xFF;
        // Single-byte (ASCII)
        if ((b0 & 0x80) == 0) {
            sb.append((char) b0);
            return i + 1;
        }

        int expectedLen;
        int value;
        if ((b0 & 0xE0) == 0xC0) {          // 2-byte sequence
            expectedLen = 2;
            value = b0 & 0x1F;
        } else if ((b0 & 0xF0) == 0xE0) {   // 3-byte sequence
            expectedLen = 3;
            value = b0 & 0x0F;
        } else if ((b0 & 0xF8) == 0xF0) {   // 4-byte sequence
            expectedLen = 4;
            value = b0 & 0x07;
        } else {
            // Invalid first byte
            sb.append('\uFFFD'); // Replacement character
            return i + 1;
        }

        // Process continuation bytes
        for (int j = 1; j < expectedLen; j++) {
            int b = bb.get() & 0xFF;
            if ((b & 0xC0) != 0x80) {
                // Invalid continuation byte
                sb.append('\uFFFD');
                return i + 1;
            }
            value = (value << 6) | (b & 0x3F);
        }

        // Convert the code point to characters and append
        if (value <= 0xFFFF) {
            sb.append((char) value);
        } else {
            // Encode surrogate pair
            int cp = value - 0x10000;
            sb.append((char) (0xD800 + (cp >> 10)));
            sb.append((char) (0xDC00 + (cp & 0x3FF)));
        }
        return i + 1;
    } catch (BufferUnderflowException e) {
        // Not enough bytes; append replacement and return
        sb.append('\uFFFD');
        return i + 1;
    }
}

