    if (relativePath.trim().isEmpty() || relativePath.equals(".")) {
        return path;
    }
    try {
        java.nio.file.Path basePath = java.nio.file.Paths.get(path);
        java.nio.file.Path resolvedPath = basePath.resolve(relativePath).normalize();
        // Ensure we return the path using forward slashes regardless of OS
        return resolvedPath.toString().replace('\\', '/');
    } catch (Exception e) {
        // Fallback manual resolution if an exception occurs
        String base = path;
        // If the base path looks like a directory (ends with '/'), keep it as is;
        // otherwise strip the last segment assuming it's a file.
        if (!base.endsWith("/")) {
            int idx = base.lastIndexOf('/');
            if (idx >= 0) {
                base = base.substring(0, idx + 1);
            } else {
                base = "";
            }
        }
        String[] relParts = relativePath.split("[/\\\\]");
        java.util.Deque<String> stack = new java.util.ArrayDeque<>();
        java.util.StringTokenizer tokenizer = new java.util.StringTokenizer(base, "/");
        while (tokenizer.hasMoreTokens()) {
            stack.addLast(tokenizer.nextToken());
        }
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
