public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    for (int i = 0; i < 10; i++) {
        int b = input.read(); // assume 'input' is an InputStream field available in the class
        if (b == -1) {
            throw new java.io.EOFException("Truncated input stream while reading raw varint64");
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint64 is too long, exceeds maximum of 10 bytes");
}

